import io

from alembic import command
from alembic.script import ScriptDirectory

from app.migrate_gen import alembic_config


def test_migrations_have_one_head() -> None:
    script = ScriptDirectory.from_config(alembic_config())
    assert len(script.get_heads()) == 1


def test_each_migration_has_the_revision_before_it() -> None:
    script = ScriptDirectory.from_config(alembic_config())
    revisions = list(script.walk_revisions())
    assert revisions[-1].down_revision is None
    for newer, older in zip(revisions, revisions[1:], strict=False):
        assert newer.down_revision == older.revision


def test_migrations_give_sql_with_no_database() -> None:
    output = io.StringIO()
    config = alembic_config()
    config.output_buffer = output
    command.upgrade(config, "heads", sql=True)
    text = output.getvalue()
    assert "CREATE TABLE" in text
    assert "CREATE TABLE alembic_version" in text
